(* [comment removed for export] *)
Definition kin_post (kidx n k : Z) (ra sp gp tp t0 t1 t2 s0 s1 a3 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 : bvmap 5 word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists (a1' a5' a6' a7' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem) (ks' : list word),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 kidx) a1' (Z_to_bv 64 n) a3 (Z_to_bv 64 k) a5' a6' a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xc35a4) fc' None m' (seg_rom asegs)
    /\ fs_agree F0 F' /\ frm0 fc' /\ munch [(kidx, kidx + 1024)] m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
    /\ u32arr asegs m' kidx ks' /\ kidx_ok 10 ks' /\ wr_at asegs m' kidx 1024 /\ acc asegs m' kidx 1024.

Lemma kidx_inner : forall (j : nat) (i n k : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a3 a6 a7 s2 s3 s4 s5 s6 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kidx : Z) (ks : list word),
  Z.of_nat j = n - i -> 0 <= i < n -> n <= 255 -> 0 <= k <= 8 ->
  0 < kidx -> kidx mod 16 = 0 -> kidx + 1024 <= 2^47 -> (kidx + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= kidx) ->
  fs_agree F0 F -> reg_get F (15%bv : bv 5) = fcvt_s_w RNE (Z_to_bv 64 n) -> frm0 fc ->
  munch [(kidx, kidx + 1024)] m0 m -> wmono asegs m0 m ->
  u32arr asegs m kidx ks -> kidx_ok 10 ks -> wr_at asegs m kidx 1024 -> acc asegs m kidx 1024 -> mem_inv asegs m ->
  evt asegs (kin_post kidx n k ra sp gp tp t0 t1 t2 s0 s1 a3 s2 s3 s4 s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6 F0 m0)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 kidx) (Z_to_bv 64 (kidx + 4 * i)) (Z_to_bv 64 i) a3 (Z_to_bv 64 k)
             (Z_to_bv 64 (kidx + 4 * i)) a6 a7 s2 s3 s4 s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 t4 t5 t6)
