(* [comment removed for export] *)
Definition kidx_post (kidx maxval : Z) (ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 : bvmap 5 word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists (a2' a3' a4' a5' a6' a7' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem) (ks' : list word),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 kidx) (Z_to_bv 64 maxval) a2' a3' a4' a5' a6' a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xc2bf4) fc' None m' (seg_rom asegs)
    /\ fs_agree F0 F' /\ frm0 fc' /\ munch [(kidx, kidx + 1024)] m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
    /\ u32arr asegs m' kidx ks' /\ kidx_ok 10 ks' /\ wr_at asegs m' kidx 1024 /\ acc asegs m' kidx 1024.

Lemma word_of_unsigned : forall w : word, w = Z_to_bv 64 (bv_unsigned w).
Proof.
ltac2:(KReplay.run1 (kr_t_Bi_bcreate_kidxloop ()) [] "h01wp;1p;2p;4g00N6j10Tg00k;j16Tg00kYj12Tg00lbj21Tg00l<j25Tg03h[j14Tg02;Qj43Tg00^L#0#0#0#0#0#0#6R0#2R1P1f0R1,10,50P1%41C3W0o"). Qed.

(* [comment removed for export] *)
Lemma kidx_latch : forall (i k : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a1 a5 a6 a7 s2 s5 s6 s8 s9 s10 t3 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kidx nc pmin pmax minval maxval S1 : Z) (ncs ks : list word),
  0 <= k <= 8 -> 0 <= i <= 255 ->
  0 < kidx -> kidx mod 16 = 0 -> kidx + 1024 <= 2^47 -> (kidx + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= kidx) ->
  0 <= maxval <= 255 ->
  (forall m', munch [(kidx, kidx + 1024)] m0 m' -> wmono asegs m0 m' -> bc_karr_ro pmin pmax minval maxval nc ncs (S1 + 104) 10 m') ->
  fs_agree F0 F -> frm0 fc ->
  munch [(kidx, kidx + 1024)] m0 m -> wmono asegs m0 m ->
  u32arr asegs m kidx ks -> kidx_ok 10 ks -> wr_at asegs m kidx 1024 -> acc asegs m kidx 1024 -> mem_inv asegs m ->
  (k + 1 < 9 -> i <= maxval -> forall (a1' a5' a6' a7' : word),
     evt asegs (kidx_post kidx maxval ra sp gp tp t0 t1 t2 s0 s1 s2 (Z_to_bv 64 pmax) (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10
                          (Z_to_bv 64 nc) t3 t4 t5 t6 F0 m0)
       (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 kidx) a1' (Z_to_bv 64 i) (Z_to_bv 64 (k + 1)) (Z_to_bv 64 (k + 1)) a5' a6' a7'
                s2 (Z_to_bv 64 pmax) (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 (Z_to_bv 64 nc) t3 t4 t5 t6)
           F (Z_to_bv 64 0xc3528) fc None m (seg_rom asegs))) ->
  evt asegs (kidx_post kidx maxval ra sp gp tp t0 t1 t2 s0 s1 s2 (Z_to_bv 64 pmax) (Z_to_bv 64 9) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10
